    constant AD9361_BAND_HZ : ad9361_band_table := (8.000000000000e+08, 2.400000000000e+09, 5.500000000000e+09);
    -- maximum RX gain (given at 800 MHz; 2300 MHz RX1A/RX2A; 5500 MHz RX1A/RX2A) [dB, ds]
    constant AD9361_T_RX_GAIN_MAX : ad9361_band_table := (7.450000000000e+01, 7.300000000000e+01, 6.550000000000e+01);
    -- noise figure at maximum RX gain [dB, ds]
    constant AD9361_T_RX_NF : ad9361_band_table := (2.000000000000e+00, 3.000000000000e+00, 3.800000000000e+00);
    -- third-order input intercept at maximum RX gain [dBm, ds]
    constant AD9361_T_RX_IIP3 : ad9361_band_table := ((-1.800000000000e+01), (-1.400000000000e+01), (-1.700000000000e+01));
    -- RX modulation accuracy (19.2 MHz reference at 800 MHz, 40 MHz at 2.4 and 5.5 GHz) [dB, ds]
    constant AD9361_T_RX_EVM : ad9361_band_table := ((-4.200000000000e+01), (-4.200000000000e+01), (-3.700000000000e+01));
    -- LO leakage at the RX front-end input [dBm, ds]
    constant AD9361_T_RX_LO_LEAK : ad9361_band_table := ((-1.220000000000e+02), (-1.100000000000e+02), (-9.500000000000e+01));
    -- maximum output power, 1 MHz tone (7 MHz at 5.5 GHz) into 50 ohm [dBm, ds]
    constant AD9361_T_TX_PMAX : ad9361_band_table := (8.000000000000e+00, 7.500000000000e+00, 6.500000000000e+00);
    -- third-order output intercept, 0 dB attenuation [dBm, ds]
    constant AD9361_T_TX_OIP3 : ad9361_band_table := (2.300000000000e+01, 1.900000000000e+01, 1.700000000000e+01);
    -- TX modulation accuracy; -40 dB at 800 MHz and 2.4 GHz were read, -36 dB at 5.5 GHz is 'rec' [dB, ds]
    constant AD9361_T_TX_EVM : ad9361_band_table := ((-4.000000000000e+01), (-4.000000000000e+01), (-3.600000000000e+01));
    -- TX noise floor at 90 MHz offset [dBm/Hz, ds]
    constant AD9361_T_TX_NOISE : ad9361_band_table := ((-1.570000000000e+02), (-1.560000000000e+02), (-1.515000000000e+02));
    -- carrier leakage at 0 dB attenuation [dBc, ds]
    constant AD9361_T_TX_LEAK_0DB : ad9361_band_table := ((-5.000000000000e+01), (-5.000000000000e+01), (-5.000000000000e+01));
    -- carrier leakage at 40 dB attenuation; -32 dBc was read, -30 dBc at 5.5 GHz is 'rec' [dBc, ds]
    constant AD9361_T_TX_LEAK_40DB : ad9361_band_table := ((-3.200000000000e+01), (-3.200000000000e+01), (-3.000000000000e+01));
    -- integrated LO phase noise; the data sheet has it as plots only, these three numbers are 'rec' [deg, rec]
    constant AD9361_T_LO_PN_RMS : ad9361_band_table := (1.300000000000e-01, 3.700000000000e-01, 5.900000000000e-01);
    constant AD9361_RX_LO_MIN : real := 7.000000000000e+07;   -- RX band [Hz, ds]
    constant AD9361_RX_LO_MAX : real := 6.000000000000e+09;   -- RX band [Hz, ds]
    constant AD9361_TX_LO_MIN : real := 4.700000000000e+07;   -- TX band [Hz, ds]
    constant AD9361_TX_LO_MAX : real := 6.000000000000e+09;   -- TX band [Hz, ds]
    constant AD9361_RX_GAIN_MIN : real := 0.000000000000e+00;   -- minimum RX gain [dB, ds]
    constant AD9361_RX_GAIN_STEP : real := 1.000000000000e+00;   -- RX gain step [dB, ds]
    constant AD9361_TX_ATTEN_MAX : real := 8.975000000000e+01;   -- TX power control range (90 dB) in 0.25 dB steps [dB, ds]
    constant AD9361_TX_ATTEN_STEP : real := 2.500000000000e-01;   -- TX power control resolution [dB, ds]
    constant AD9361_RX_QUAD_GAIN_ERR : real := 2.000000000000e-01;   -- RX quadrature gain error [%, ds]
    constant AD9361_RX_QUAD_PHASE_ERR : real := 2.000000000000e-01;   -- RX quadrature phase error [deg, ds]
    constant AD9361_RSSI_RANGE : real := 1.000000000000e+02;   -- RSSI range [dB, ds]
    constant AD9361_RSSI_ACCURACY : real := 2.000000000000e+00;   -- RSSI accuracy (+/-) [dB, ds]
    constant AD9361_LO_STEP : real := 2.400000000000e+00;   -- maximum LO step size [Hz, ds]
    constant AD9361_BW_MIN : real := 2.000000000000e+05;   -- tunable channel bandwidth, lower end (given as '<200 kHz') [Hz, ds]
    constant AD9361_BW_MAX : real := 5.600000000000e+07;   -- tunable channel bandwidth, upper end [Hz, ds]
    constant AD9361_ADC_BITS : real := 1.200000000000e+01;   -- ADC and DAC word length at the data port [bit, ds]
    constant AD9361_RATE_MAX : real := 6.144000000000e+07;   -- maximum data-port sample rate [Hz, rec]
    constant AD9361_RATE_MIN : real := 5.208333333333e+05;   -- minimum data-port sample rate (25 MSPS ADC, decimation 12 x 4) [Hz, rec]
    constant AD9361_RX_ISOLATION : real := 6.500000000000e+01;   -- RX1 to RX2 isolation (RX1A to RX2A; read from a Rev. F copy) [dB, ds]
    constant AD9361_TX_ISOLATION : real := 5.000000000000e+01;   -- TX1 to TX2 isolation [dB, ds]
    constant AD9361_ADC_FS_AT_0DB : real := 5.900000000000e+00;   -- CW power at the 50 ohm input that reaches ADC full scale at 0 dB gain: 0.625 V peak [dBm, ez]
    -- the model's own assumptions (ad9361.py MODEL)
    constant AD9361_RX_IIP3_CEILING : real := 2.000000000000e+01;
    constant AD9361_PN_CORNER : real := 1.000000000000e+05;
    constant AD9361_RX_BBLPF_CORNER : real := 1.400000000000e+00;
    constant AD9361_RX_TIA_CORNER : real := 2.500000000000e+00;
    constant AD9361_TX_BBLPF_CORNER : real := 1.600000000000e+00;
    constant AD9361_TX_SECONDARY_CORNER : real := 5.000000000000e+00;
    constant AD9361_AGC_PERIOD : real := 1.000000000000e-03;
    constant AD9361_AGC_INNER_HIGH : real := (-1.000000000000e+01);
    constant AD9361_AGC_INNER_LOW : real := (-1.200000000000e+01);
    constant AD9361_AGC_OUTER_HIGH : real := (-5.000000000000e+00);
    constant AD9361_AGC_OUTER_LOW : real := (-1.800000000000e+01);
    constant AD9361_AGC_STEP_INNER : real := 1.000000000000e+00;
    constant AD9361_AGC_STEP_OUTER : real := 4.000000000000e+00;
    constant AD9361_FAST_DETECT : real := (-1.800000000000e+01);
    constant AD9361_FAST_TARGET : real := (-1.200000000000e+01);
    constant AD9361_FAST_CLIP_STEP : real := 1.200000000000e+01;
    constant AD9361_FAST_STRONGER : real := 9.000000000000e+00;
    constant AD9361_FAST_LOST : real := 1.500000000000e+01;
    constant AD9361_FAST_BLOCK : natural := 16;
    constant AD9361_FAST_SETTLE_ITERATIONS : natural := 4;
    constant AD9361_FAST_LOST_BLOCKS : natural := 8;

    type ad9361_ensm is (ENSM_SLEEP, ENSM_ALERT, ENSM_RX, ENSM_TX, ENSM_FDD);
    type ad9361_agc_mode is (AGC_MANUAL, AGC_SLOW_ATTACK, AGC_FAST_ATTACK);

    type ad9361_config is record
        rx_lo       : real;          -- Hz
        tx_lo       : real;          -- Hz
        sample_rate : real;          -- Hz, the data-port rate (sets the noise band)
        rx_rf_bw    : real;          -- Hz, RX RF bandwidth (sets the analog baseband filter corners)
        tx_rf_bw    : real;          -- Hz, TX RF bandwidth
        gain_mode   : ad9361_agc_mode;
