                                     -- handed one); ad9361_rx_gain_legal gives the nearest the 1 dB table has
        tx_atten_db : real;          -- TX attenuation, dB, 0 .. 89.75 in 0.25 dB steps
        xo_ppm      : real;          -- reference clock error; moves both LOs
        ensm        : ad9361_ensm;   -- ENSM_RX: transmitter silent; ENSM_TX: receiver gives zeros
    end record;

    -- what the noisy sample procedures carry from one sample to the next
    type ad9361_state is record
        seed1, seed2  : positive;
        rx_theta      : real;        -- RX LO phase noise, rad
        tx_theta      : real;        -- TX LO phase noise, rad
        tx_leak_phase : real;        -- phase of the carrier leakage, rad
