    function ad9361_default_config return ad9361_config;
    function ad9361_init_state(seed : positive) return ad9361_state;

    -- a band table at LO frequency f: linear in log10(f) between the three bands, held outside
    function ad9361_band(t : ad9361_band_table; f : real) return real;
    function ad9361_rx_gain_max(f : real) return real;
    function ad9361_rx_gain_legal(f : real; g : real) return real;
    function ad9361_lo_actual(f : real; ppm : real) return real;
    -- CW power at the RX port that reaches ADC full scale, dBm
    function ad9361_rx_full_scale_dbm(cfg : ad9361_config) return real;
    -- output power of a full-scale tone at the present attenuation, dBm
    function ad9361_tx_full_scale_dbm(cfg : ad9361_config) return real;
    -- thermal noise referred to the RX port in the sampled band, dBm
    function ad9361_rx_noise_floor_dbm(cfg : ad9361_config) return real;

    -- Noise-free memoryless paths.  code: I and Q of the data-port word; transmit in 16-bit units
    -- (full scale 2**15, the 12-bit DAC word in the upper bits), receive -2048 .. 2047.
    function ad9361_tx_ideal(cfg : ad9361_config; code : iq_sample) return rf_signal;
    function ad9361_rx_ideal(cfg : ad9361_config; s : rf_signal) return iq_sample;

    -- One sample with noise, LO phase noise, EVM residual, carrier leakage and quadrature errors.
    -- t: time of the sample in seconds (turns a carrier offset between s.freq and the RX LO into rotation).
    procedure ad9361_tx_sample(cfg : in ad9361_config; st : inout ad9361_state; code : in iq_sample;
                               s : out rf_signal);
    procedure ad9361_rx_sample(cfg : in ad9361_config; st : inout ad9361_state; s : in rf_signal; t : in real;
                               code : out iq_sample);

    -- Slow-attack AGC: the gain for the next period from the mean ADC power of the last one (dBFS)
    function ad9361_agc_slow(cfg : ad9361_config; p_dbfs : real) return real;

    -- The chip's constants in a control state, as one vector: for an accelerator that runs this model
    -- outside the simulator (accel/spectral_accel.h, enum SA_P_*).  lines: samples per event.
    constant AD9361_ACCEL_N : positive := 49;      -- its length
    function ad9361_accel_params(cfg : ad9361_config; lines : positive) return real_vector;
