package body ad9361_pkg is
    constant K_BOLTZ : real := 1.380649e-23;
    constant T0 : real := 290.0;

    function dbm_w(dbm : real) return real is
    begin
        return 1.0e-3 * 10.0 ** (dbm / 10.0);
    end function;

    function w_dbm(w : real) return real is
    begin
        return 10.0 * log10(realmax(w, 1.0e-300) / 1.0e-3);
    end function;

    function ad9361_default_config return ad9361_config is
    begin
        return (rx_lo => 2.4e9, tx_lo => 2.4e9, sample_rate => 30.72e6, rx_rf_bw => 18.0e6, tx_rf_bw => 18.0e6,
                gain_mode => AGC_MANUAL, rx_gain_db => AD9361_T_RX_GAIN_MAX(1), tx_atten_db => 10.0, xo_ppm => 0.0,
                ensm => ENSM_FDD);
    end function;

    function ad9361_init_state(seed : positive) return ad9361_state is
        variable st : ad9361_state := (seed1 => seed, seed2 => 12345, rx_theta => 0.0, tx_theta => 0.0,
                                       tx_leak_phase => 0.0);
        variable u : real;
    begin
        uniform(st.seed1, st.seed2, u);
        st.tx_leak_phase := 2.0 * MATH_PI * u;
        return st;
    end function;

    function ad9361_band(t : ad9361_band_table; f : real) return real is
        constant x  : real := log10(realmax(realmin(f, AD9361_BAND_HZ(2)), AD9361_BAND_HZ(0)));
        constant x0 : real := log10(AD9361_BAND_HZ(0));
        constant x1 : real := log10(AD9361_BAND_HZ(1));
        constant x2 : real := log10(AD9361_BAND_HZ(2));
    begin
        if x <= x1 then
            return t(0) + (t(1) - t(0)) * (x - x0) / (x1 - x0);
        end if;
        return t(1) + (t(2) - t(1)) * (x - x1) / (x2 - x1);
    end function;

    function ad9361_rx_gain_max(f : real) return real is
    begin
        return ad9361_band(AD9361_T_RX_GAIN_MAX, f);
    end function;

    function ad9361_rx_gain_legal(f : real; g : real) return real is
        constant gmax : real := ad9361_rx_gain_max(f);
        constant kmax : real := floor((gmax - AD9361_RX_GAIN_MIN) / AD9361_RX_GAIN_STEP);
        variable k : real := floor((gmax - g) / AD9361_RX_GAIN_STEP + 0.5);
    begin
        k := realmax(0.0, realmin(k, kmax));
        return gmax - k * AD9361_RX_GAIN_STEP;
    end function;

    function ad9361_lo_actual(f : real; ppm : real) return real is
    begin
        return floor(f * (1.0 + ppm * 1.0e-6) / AD9361_LO_STEP + 0.5) * AD9361_LO_STEP;
    end function;

    function ad9361_rx_full_scale_dbm(cfg : ad9361_config) return real is
    begin
        return AD9361_ADC_FS_AT_0DB - cfg.rx_gain_db;
    end function;

    function ad9361_rx_noise_floor_dbm(cfg : ad9361_config) return real is
    begin
        return w_dbm(K_BOLTZ * T0 * cfg.sample_rate) + ad9361_band(AD9361_T_RX_NF, cfg.rx_lo);
    end function;

    -- linear (uncompressed) power of a full-scale tone at 0 dB attenuation: such that the compressed
    -- output is the data sheet's maximum output power
    function tx_lin_w(f : real) return real is
        constant pmax : real := dbm_w(ad9361_band(AD9361_T_TX_PMAX, f));
        constant ip3  : real := dbm_w(ad9361_band(AD9361_T_TX_OIP3, f));
    begin
        return pmax / (1.0 - 2.0 * pmax / ip3);
    end function;

    -- output power of a full-scale tone at power attenuation ratio att (attenuator before the output stage)
    function tx_carrier_w(f : real; att : real) return real is
        constant p : real := tx_lin_w(f) * att;
    begin
        return p / (1.0 + 2.0 * p / dbm_w(ad9361_band(AD9361_T_TX_OIP3, f)));
    end function;

    -- carrier leakage: one part follows the attenuator, one does not (the data sheet's 0 and 40 dB points)
    function tx_leak_w(f : real; att : real) return real is
        constant p0  : real := tx_carrier_w(f, 1.0) * 10.0 ** (ad9361_band(AD9361_T_TX_LEAK_0DB, f) / 10.0);
        constant p40 : real := tx_carrier_w(f, 1.0e-4) * 10.0 ** (ad9361_band(AD9361_T_TX_LEAK_40DB, f) / 10.0);
        constant la  : real := (p0 - p40) / (1.0 - 1.0e-4);
    begin
        return la * att + (p0 - la);
    end function;

    function ad9361_tx_full_scale_dbm(cfg : ad9361_config) return real is
    begin
        return w_dbm(tx_carrier_w(cfg.tx_lo, 10.0 ** (-cfg.tx_atten_db / 10.0)));
    end function;

    -- signal-proportional error left to reach the data sheet EVM beside the explicit terms (power ratio)
    function residual(evm_db : real; pn_deg : real; other : real) return real is
        constant pn : real := pn_deg * MATH_PI / 180.0;
    begin
        return realmax(10.0 ** (evm_db / 10.0) - pn * pn - other, 0.0);
    end function;

    function image_ratio return real is
        constant e : real := AD9361_RX_QUAD_GAIN_ERR / 100.0;
        constant p : real := AD9361_RX_QUAD_PHASE_ERR * MATH_PI / 180.0;
    begin
        return (e * e + p * p) / 4.0;
    end function;

    -- two independent unit Gaussians
    procedure gauss(st : inout ad9361_state; g1, g2 : out real) is
        variable u1, u2, r : real;
    begin
        uniform(st.seed1, st.seed2, u1);
        uniform(st.seed1, st.seed2, u2);
        r := sqrt(-2.0 * log(realmax(u1, 1.0e-300)));
        g1 := r * cos(2.0 * MATH_PI * u2);
        g2 := r * sin(2.0 * MATH_PI * u2);
    end procedure;

    -- one step of the first-order phase noise process
    procedure phase_step(st : inout ad9361_state; theta : inout real; rms_deg : in real; fs : in real) is
        constant a : real := exp(-2.0 * MATH_PI * AD9361_PN_CORNER / fs);
        variable g1, g2 : real;
    begin
        gauss(st, g1, g2);
        theta := a * theta + g1 * (rms_deg * MATH_PI / 180.0) * sqrt(1.0 - a * a);
    end procedure;

    function dac_word(x : real) return real is
    begin
        return realmax(-2048.0, realmin(2047.0, floor(x / 16.0 + 0.5))) / 2048.0;
    end function;

    function adc_word(x : real) return real is
    begin
        return realmax(-2048.0, realmin(2047.0, floor(x * 2048.0 + 0.5)));
    end function;

    -- the attenuator and the compressing output stage, on a DAC value (full scale 1.0)
    procedure tx_core(cfg : in ad9361_config; qi, qq : in real; yi, yq : out real) is
        constant att : real := 10.0 ** (-cfg.tx_atten_db / 10.0);
        constant a   : real := sqrt(tx_lin_w(cfg.tx_lo) * att);
        constant ip3 : real := dbm_w(ad9361_band(AD9361_T_TX_OIP3, cfg.tx_lo));
        constant xi  : real := qi * a;
        constant xq  : real := qq * a;
        constant k   : real := 1.0 / sqrt(1.0 + 2.0 * (xi * xi + xq * xq) / ip3);
    begin
        yi := xi * k;
        yq := xq * k;
    end procedure;

    -- compression, gain and the ADC, on an envelope at the RX port
    procedure rx_core(cfg : in ad9361_config; ai, aq : in real; ci, cq : out real) is
        constant gmax : real := ad9361_rx_gain_max(cfg.rx_lo);
        constant iip3 : real := dbm_w(realmin(ad9361_band(AD9361_T_RX_IIP3, cfg.rx_lo) + (gmax - cfg.rx_gain_db),
                                              AD9361_RX_IIP3_CEILING));
        constant k    : real := 1.0 / sqrt(1.0 + 2.0 * (ai * ai + aq * aq) / iip3);
        constant g    : real := sqrt(10.0 ** (cfg.rx_gain_db / 10.0) / dbm_w(AD9361_ADC_FS_AT_0DB));
    begin
        ci := adc_word(ai * k * g);
        cq := adc_word(aq * k * g);
    end procedure;

    function ad9361_tx_ideal(cfg : ad9361_config; code : iq_sample) return rf_signal is
        variable yi, yq : real;
    begin
        if cfg.ensm /= ENSM_TX and cfg.ensm /= ENSM_FDD then
            return (0.0, 0.0, 0.0, 0.0, ad9361_lo_actual(cfg.tx_lo, cfg.xo_ppm));
        end if;
        tx_core(cfg, dac_word(code.i), dac_word(code.q), yi, yq);
        return (eh_re => yi, eh_im => yq, ev_re => 0.0, ev_im => 0.0, freq => ad9361_lo_actual(cfg.tx_lo, cfg.xo_ppm));
    end function;

    function ad9361_rx_ideal(cfg : ad9361_config; s : rf_signal) return iq_sample is
        variable ci, cq : real;
    begin
        if cfg.ensm /= ENSM_RX and cfg.ensm /= ENSM_FDD then
            return IQ_ZERO;
        end if;
        rx_core(cfg, s.eh_re, s.eh_im, ci, cq);
        return (i => ci, q => cq);
    end function;

    procedure ad9361_tx_sample(cfg : in ad9361_config; st : inout ad9361_state; code : in iq_sample;
                               s : out rf_signal) is
        constant f   : real := cfg.tx_lo;
        constant att : real := 10.0 ** (-cfg.tx_atten_db / 10.0);
        constant res : real := residual(ad9361_band(AD9361_T_TX_EVM, f), ad9361_band(AD9361_T_LO_PN_RMS, f), 0.0);
        constant nw  : real := realmax(dbm_w(ad9361_band(AD9361_T_TX_NOISE, f)) * att, K_BOLTZ * T0) * cfg.sample_rate;
        constant lk  : real := sqrt(tx_leak_w(f, att));
        variable qi, qq, ei, eq, ti, tq, yi, yq, g1, g2 : real;
    begin
        if cfg.ensm /= ENSM_TX and cfg.ensm /= ENSM_FDD then
            s := (0.0, 0.0, 0.0, 0.0, ad9361_lo_actual(f, cfg.xo_ppm));
            return;
        end if;
        phase_step(st, st.tx_theta, ad9361_band(AD9361_T_LO_PN_RMS, f), cfg.sample_rate);
        qi := dac_word(code.i);
        qq := dac_word(code.q);
        gauss(st, g1, g2);                                   -- (1 + e), e complex Gaussian of power res
        ei := 1.0 + g1 * sqrt(res / 2.0);
        eq := g2 * sqrt(res / 2.0);
        ti := qi * ei - qq * eq;
        tq := qi * eq + qq * ei;
        qi := ti * cos(st.tx_theta) - tq * sin(st.tx_theta);
        qq := ti * sin(st.tx_theta) + tq * cos(st.tx_theta);
        tx_core(cfg, qi, qq, yi, yq);
        gauss(st, g1, g2);
        yi := yi + lk * cos(st.tx_leak_phase) + g1 * sqrt(nw / 2.0);
        yq := yq + lk * sin(st.tx_leak_phase) + g2 * sqrt(nw / 2.0);
        s := (eh_re => yi, eh_im => yq, ev_re => 0.0, ev_im => 0.0, freq => ad9361_lo_actual(f, cfg.xo_ppm));
    end procedure;

    procedure ad9361_rx_sample(cfg : in ad9361_config; st : inout ad9361_state; s : in rf_signal; t : in real;
                               code : out iq_sample) is
        constant f   : real := cfg.rx_lo;
        constant res : real := residual(ad9361_band(AD9361_T_RX_EVM, f), ad9361_band(AD9361_T_LO_PN_RMS, f), image_ratio);
        constant nw  : real := K_BOLTZ * T0 * cfg.sample_rate * 10.0 ** (ad9361_band(AD9361_T_RX_NF, f) / 10.0);
        constant e   : real := AD9361_RX_QUAD_GAIN_ERR / 100.0;
        constant p   : real := AD9361_RX_QUAD_PHASE_ERR * MATH_PI / 180.0;
        constant df  : real := s.freq - ad9361_lo_actual(f, cfg.xo_ppm);
        variable th, ai, aq, ei, eq, ti, tq, g1, g2, ci, cq : real;
    begin
        if cfg.ensm /= ENSM_RX and cfg.ensm /= ENSM_FDD then
            code := IQ_ZERO;
            return;
        end if;
        phase_step(st, st.rx_theta, ad9361_band(AD9361_T_LO_PN_RMS, f), cfg.sample_rate);
        th := st.rx_theta;
        if df /= 0.0 and s.freq >= 0.0 then
            th := th + 2.0 * MATH_PI * df * t;
        end if;
        ai := s.eh_re * cos(th) - s.eh_im * sin(th);
        aq := s.eh_re * sin(th) + s.eh_im * cos(th);
        gauss(st, g1, g2);
        ei := 1.0 + g1 * sqrt(res / 2.0);
        eq := g2 * sqrt(res / 2.0);
        ti := ai * ei - aq * eq;
        tq := ai * eq + aq * ei;
        gauss(st, g1, g2);
        ti := ti + g1 * sqrt(nw / 2.0);
        tq := tq + g2 * sqrt(nw / 2.0);
        ai := ti;                                            -- quadrature errors: gain and phase on Q
        aq := (1.0 + e) * (tq * cos(p) + ti * sin(p));
        rx_core(cfg, ai, aq, ci, cq);
        code := (i => ci, q => cq);
    end procedure;

    function ad9361_agc_slow(cfg : ad9361_config; p_dbfs : real) return real is
        variable g : real := cfg.rx_gain_db;
    begin
        if p_dbfs > AD9361_AGC_OUTER_HIGH then
            g := g - AD9361_AGC_STEP_OUTER;
        elsif p_dbfs > AD9361_AGC_INNER_HIGH then
            g := g - AD9361_AGC_STEP_INNER;
        elsif p_dbfs < AD9361_AGC_OUTER_LOW then
            g := g + AD9361_AGC_STEP_OUTER;
        elsif p_dbfs < AD9361_AGC_INNER_LOW then
            g := g + AD9361_AGC_STEP_INNER;
        end if;
        return ad9361_rx_gain_legal(cfg.rx_lo, g);
    end function;

    function ad9361_accel_params(cfg : ad9361_config; lines : positive) return real_vector is
        constant ftx : real := cfg.tx_lo;
        constant frx : real := cfg.rx_lo;
        constant att : real := 10.0 ** (-cfg.tx_atten_db / 10.0);
        constant a   : real := exp(-2.0 * MATH_PI * AD9361_PN_CORNER / cfg.sample_rate);
        constant e   : real := AD9361_RX_QUAD_GAIN_ERR / 100.0;
        constant ph  : real := AD9361_RX_QUAD_PHASE_ERR * MATH_PI / 180.0;
        variable p : real_vector(0 to AD9361_ACCEL_N - 1) := (others => 0.0);

        function flag(b : boolean) return real is
        begin
            if b then
                return 1.0;
            end if;
            return 0.0;
        end function;
    begin
        p(0) := 1.0;                                         -- layout version
        p(1) := real(lines);
        p(2) := cfg.sample_rate;
        p(3) := flag(cfg.ensm = ENSM_TX or cfg.ensm = ENSM_FDD);
        p(4) := flag(cfg.ensm = ENSM_RX or cfg.ensm = ENSM_FDD);
        p(5) := ad9361_lo_actual(ftx, cfg.xo_ppm);
        p(6) := ad9361_lo_actual(frx, cfg.xo_ppm);
        -- transmitter (ad9361_tx_sample)
        p(7) := sqrt(tx_lin_w(ftx) * att);
        p(8) := dbm_w(ad9361_band(AD9361_T_TX_OIP3, ftx));
        p(9) := sqrt(residual(ad9361_band(AD9361_T_TX_EVM, ftx), ad9361_band(AD9361_T_LO_PN_RMS, ftx), 0.0) / 2.0);
        p(10) := a;
        p(11) := ad9361_band(AD9361_T_LO_PN_RMS, ftx) * MATH_PI / 180.0 * sqrt(1.0 - a * a);
        p(12) := sqrt(tx_leak_w(ftx, att));
        p(13) := sqrt(realmax(dbm_w(ad9361_band(AD9361_T_TX_NOISE, ftx)) * att, K_BOLTZ * T0) * cfg.sample_rate / 2.0);
        p(14) := AD9361_TX_BBLPF_CORNER * cfg.tx_rf_bw / 2.0;
        p(15) := AD9361_TX_SECONDARY_CORNER * cfg.tx_rf_bw / 2.0;
        -- receiver (ad9361_rx_sample)
        p(16) := sqrt(residual(ad9361_band(AD9361_T_RX_EVM, frx), ad9361_band(AD9361_T_LO_PN_RMS, frx), image_ratio) / 2.0);
        p(17) := a;
        p(18) := ad9361_band(AD9361_T_LO_PN_RMS, frx) * MATH_PI / 180.0 * sqrt(1.0 - a * a);
        p(19) := sqrt(K_BOLTZ * T0 * cfg.sample_rate * 10.0 ** (ad9361_band(AD9361_T_RX_NF, frx) / 10.0) / 2.0);
        p(20) := 1.0 + e;
        p(21) := cos(ph);
        p(22) := sin(ph);
        p(23) := ad9361_band(AD9361_T_RX_IIP3, frx);
        p(24) := ad9361_rx_gain_max(frx);
        p(25) := AD9361_RX_GAIN_MIN;
        p(26) := AD9361_RX_GAIN_STEP;
        p(27) := AD9361_RX_IIP3_CEILING;
        p(28) := dbm_w(AD9361_ADC_FS_AT_0DB);
        p(29) := AD9361_RX_BBLPF_CORNER * cfg.rx_rf_bw / 2.0;
        p(30) := AD9361_RX_TIA_CORNER * cfg.rx_rf_bw / 2.0;
        p(31) := sqrt(dbm_w(ad9361_band(AD9361_T_RX_LO_LEAK, frx)));
        -- gain control
        p(32) := real(ad9361_agc_mode'pos(cfg.gain_mode));
        p(33) := ad9361_rx_gain_legal(frx, cfg.rx_gain_db);
        p(34) := AD9361_FAST_DETECT;
        p(35) := AD9361_FAST_TARGET;
        p(36) := AD9361_FAST_CLIP_STEP;
        p(37) := AD9361_FAST_STRONGER;
        p(38) := AD9361_FAST_LOST;
        p(39) := real(AD9361_FAST_BLOCK);
        p(40) := real(AD9361_FAST_SETTLE_ITERATIONS);
        p(41) := real(AD9361_FAST_LOST_BLOCKS);
        p(42) := round(AD9361_AGC_PERIOD * cfg.sample_rate);
        p(43) := AD9361_AGC_INNER_HIGH;
        p(44) := AD9361_AGC_INNER_LOW;
        p(45) := AD9361_AGC_OUTER_HIGH;
        p(46) := AD9361_AGC_OUTER_LOW;
        p(47) := AD9361_AGC_STEP_INNER;
        p(48) := AD9361_AGC_STEP_OUTER;
        return p;
    end function;
end package body;
